37	// Where a native check points, by the ids the project model gives it. The
38	// print works on its own copy of the model, whose ids are the project's.
39	void set_target(PrintIssue& issue, const ModelObject* object, const ModelInstance* instance)
40	{
41	    if (instance != nullptr) {
42	        issue.instance = instance->id().id;
43	        object = instance->get_object();
44	    }
45	    if (object != nullptr) {
46	        issue.object      = object->id().id;
47	        issue.object_name = object->name;
48	    }
49	}
50	
51	void set_target(PrintIssue& issue, const ObjectBase* target)
52	{
53	    if (target == nullptr)
54	        return;
55	    if (const auto* instance = dynamic_cast<const ModelInstance*>(target))
56	        set_target(issue, nullptr, instance);
57	    else if (const auto* print_object = dynamic_cast<const PrintObjectBase*>(target))
58	        set_target(issue, print_object->model_object(), nullptr);
59	    else if (const auto* object = dynamic_cast<const ModelObject*>(target))
60	        set_target(issue, object, nullptr);
61	}
62	
63	std::string target_key(const PrintIssue& issue)
64	{
65	    return std::to_string(issue.object) + ":" + std::to_string(issue.instance);
66	}
67	
68	// OrcaSlicer sets the check type on some results and leaves it unset on
69	// others, so only a value it defines is reported.
70	std::string check_name(StringExceptionType type)
71	{
72	    switch (type) {
73	    case STRING_EXCEPT_FILAMENT_NOT_MATCH_BED_TYPE:     return "filament_not_match_bed_type";
74	    case STRING_EXCEPT_FILAMENTS_DIFFERENT_TEMP:        return "filaments_different_temp";
75	    case STRING_EXCEPT_OBJECT_COLLISION_IN_SEQ_PRINT:   return "object_collision_in_seq_print";
76	    case STRING_EXCEPT_OBJECT_COLLISION_IN_LAYER_PRINT: return "object_collision_in_layer_print";
77	    case STRING_EXCEPT_LAYER_HEIGHT_EXCEEDS_LIMIT:      return "layer_height_exceeds_limit";
78	    default:                                            return {};
79	    }
80	}
81	
82	PrintIssue plate_issue(PartPlate& plate, IssueSource source, IssueSeverity severity, std::string code, std::string message)
83	{
84	    PrintIssue issue;
85	    issue.source   = source;
86	    issue.severity = severity;
87	    issue.code     = std::move(code);
88	    issue.message  = std::move(message);
89	    issue.plate    = plate.id().id;
90	    issue.id       = std::string(source_name(source)) + ":" + issue.code;
91	    return issue;
92	}
