94	// "1, 3" for filaments 0 and 2: OrcaSlicer counts them from one for people.
95	std::string filament_numbers(const std::set<int>& filaments)
96	{
97	    std::string text;
98	    for (const int filament : filaments)
99	        text += (text.empty() ? "" : ", ") + std::to_string(filament + 1);
100	    return text;
101	}
