105	PrintIssueMonitor::PrintIssueMonitor(Plater& plater)
106	    : m_plater(plater), m_self(std::make_shared<PrintIssueMonitor*>(this))
107	{
108	    wxASSERT(wxIsMainThread());
109	    m_project_subscription = m_plater.subscribe_project_state([this](const ProjectStateChanged& change) {
110	        const auto has = [&change](ProjectStateChangeReason reason) {
111	            return (static_cast<std::uint32_t>(change.reasons) & static_cast<std::uint32_t>(reason)) != 0;
112	        };
113	        if (change.project_replaced) {
114	            m_failures.clear();
115	            m_validation.clear();
116	            m_result = {};
117	        }
118	        if (change.project_replaced || has(ProjectStateChangeReason::Objects) || has(ProjectStateChangeReason::Transform) ||
119	            has(ProjectStateChangeReason::Plates) || has(ProjectStateChangeReason::Project) ||
120	            has(ProjectStateChangeReason::Settings))
121	            ++m_project_changes;
122	        schedule();
123	    });
124	    // The four moments OrcaSlicer's own state can move without the project
125	    // changing: it re-evaluated whether the plate can be sliced or printed,
126	    // one of the Plater's timers fired (the deferred update of the print is
127	    // one of them; they cannot be told apart from outside, and a recompute
128	    // too many costs nothing), a slicing step reported a warning, and a slice
129	    // ended.
130	    m_plater.Bind(EVT_SLICE_STATUS_CHANGED, &PrintIssueMonitor::on_slice_status, this);
131	    m_plater.Bind(wxEVT_TIMER, &PrintIssueMonitor::on_timer, this);
132	    m_plater.Bind(EVT_SLICING_UPDATE, &PrintIssueMonitor::on_slicing_update, this);
133	    m_plater.Bind(EVT_PROCESS_COMPLETED, &PrintIssueMonitor::on_process_completed, this);
134	    schedule();
135	}
136	
137	PrintIssueMonitor::~PrintIssueMonitor()
138	{
139	    wxASSERT(wxIsMainThread());
140	    m_plater.Unbind(EVT_SLICE_STATUS_CHANGED, &PrintIssueMonitor::on_slice_status, this);
141	    m_plater.Unbind(wxEVT_TIMER, &PrintIssueMonitor::on_timer, this);
142	    m_plater.Unbind(EVT_SLICING_UPDATE, &PrintIssueMonitor::on_slicing_update, this);
143	    m_plater.Unbind(EVT_PROCESS_COMPLETED, &PrintIssueMonitor::on_process_completed, this);
144	}
145	
146	void PrintIssueMonitor::on_slice_status(wxCommandEvent& event)
147	{
148	    event.Skip();
149	    schedule();
150	}
151	
152	void PrintIssueMonitor::on_timer(wxTimerEvent& event)
153	{
154	    // OrcaSlicer's own handler applies the edit when this returns; the
155	    // recompute is queued, so it reads the print after that.
156	    event.Skip();
157	    schedule();
158	}
159	
160	void PrintIssueMonitor::on_slicing_update(SlicingStatusEvent& event)
161	{
162	    event.Skip();
163	    if (event.status.flags &
164	        (PrintBase::SlicingStatus::UPDATE_PRINT_STEP_WARNINGS | PrintBase::SlicingStatus::UPDATE_PRINT_OBJECT_STEP_WARNINGS))
165	        schedule();
166	}
167	
168	void PrintIssueMonitor::on_process_completed(SlicingProcessCompletedEvent& event)
169	{
170	    event.Skip();
171	    if (event.error()) {
172	        PartPlate* plate = m_plater.get_partplate_list().get_curr_plate();
173	        if (plate != nullptr) {
174	            SliceFailure failure;
175	            const auto   message = event.format_error_message();
176	            failure.message        = message.first;
177	            failure.critical       = event.critical_error();
178	            failure.project_change = m_project_changes;
179	            // The same lookup OrcaSlicer's own handler makes: an id that is
180	            // not a print object's names nothing.
181	            if (const Print* print = plate->fff_print())
182	                for (const std::size_t id : message.second)
183	                    if (const PrintObject* object = print->get_object(ObjectID(id)); object != nullptr && object->model_object() != nullptr)
184	                        failure.objects.push_back(object->model_object()->id().id);
185	            m_failures[plate->id().id] = std::move(failure);
186	        }
187	    }
188	    schedule();
189	}
190	
191	void PrintIssueMonitor::schedule()
192	{
193	    if (m_scheduled)
194	        return;
195	    m_scheduled = true;
196	    wxGetApp().CallAfter([self = std::weak_ptr<PrintIssueMonitor*>(m_self)]() {
197	        if (const auto monitor = self.lock()) {
198	            (*monitor)->m_scheduled = false;
199	            (*monitor)->recompute();
200	        }
201	    });
202	}
203	
204	void PrintIssueMonitor::refresh_now()
205	{
206	    wxASSERT(wxIsMainThread());
207	    recompute();
208	}
209	
210	void PrintIssueMonitor::recompute()
211	{
212	    PrintIssueSnapshot next;
213	    next.session    = m_plater.project_state_session();
214	    next.generation = m_snapshot.generation;
215	
216	    PartPlate* plate = m_plater.get_partplate_list().get_curr_plate();
217	    Print*     print = plate != nullptr ? plate->fff_print() : nullptr;
218	    if (plate != nullptr && print != nullptr && m_plater.printer_technology() == ptFFF) {
219	        next.plate   = plate->id().id;
220	        next.slicing = m_plater.is_background_process_slicing();
221	        next.sliced  = plate->is_slice_result_valid();
222	        // A slice that started replaces whatever the last one failed with.
223	        if ((next.slicing && !m_was_slicing) || next.sliced)
224	            m_failures.erase(next.plate);
225	        m_was_slicing = next.slicing;
226	
227	        // OrcaSlicer applies an edit to the print on a short timer. Until it
228	        // has, the print describes the project as it was, so nothing read
229	        // from it is current.
230	        next.checked = !m_plater.is_background_process_update_scheduled();
231	        if (next.checked) {
232	            collect_placement(*plate, next.issues);
233	            collect_plate_checks(*plate, next.issues);
234	            collect_validation(*plate, *print, next.issues);
235	            collect_steps(*plate, *print, next.issues);
236	            collect_result(*plate, *print, next.issues);
237	            collect_failure(*plate, next.issues);
238	        } else {
239	            // What it last said, kept and marked: not vouched for, not gone.
240	            // An object that no longer exists has no issue to keep.
241	            std::set<std::uint64_t> objects, instances;
242	            for (const ModelObject* object : m_plater.model().objects) {
243	                objects.insert(object->id().id);
244	                for (const ModelInstance* instance : object->instances)
245	                    instances.insert(instance->id().id);
246	            }
247	            for (PrintIssue issue : m_snapshot.issues) {
248	                if (issue.plate != next.plate || (issue.object != 0 && objects.count(issue.object) == 0) ||
249	                    (issue.instance != 0 && instances.count(issue.instance) == 0))
250	                    continue;
251	                issue.stale = true;
252	                next.issues.push_back(std::move(issue));
253	            }
254	        }
255	    }
256	
257	    if (next.same_content(m_snapshot))
258	        return;
259	    ++next.generation;
260	    m_snapshot = std::move(next);
261	    if (m_changed)
262	        m_changed();
263	}
264	
265	// A copy that straddles the plate's edge, which refuses to slice, and a
266	// filament placed where its nozzle cannot reach. OrcaSlicer stores the first
267	// on each copy when it updates the print and works out the second, with the
268	// words for both, in the canvas check its own validation calls.
269	void PrintIssueMonitor::collect_placement(PartPlate& plate, std::vector<PrintIssue>& issues) const
270	{
271	    GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
272	    if (canvas == nullptr)
273	        return;
274	    ObjectFilamentResults results;
275	    canvas->check_volumes_outside_state(&results);
276	
277	    for (const ModelObject* object : m_plater.model().objects)
278	        for (const ModelInstance* instance : object->instances) {
279	            if (!object->printable || !instance->printable || instance->print_volume_state != ModelInstancePVS_Partly_Outside)
280	                continue;
281	            PrintIssue issue = plate_issue(plate, IssueSource::Placement, IssueSeverity::Blocker, "partly_outside_plate",
282	                                           get_object_clashed_text());
283	            set_target(issue, nullptr, instance);
284	            issue.id += ":" + target_key(issue);
285	            issues.push_back(std::move(issue));
286	        }
287	    if (!get_left_extruder_unprintable_text().empty())
288	        issues.push_back(plate_issue(plate, IssueSource::Placement, IssueSeverity::Blocker, "left_nozzle_unprintable",
289	                                     get_left_extruder_unprintable_text()));
290	    if (!get_right_extruder_unprintable_text().empty())
291	        issues.push_back(plate_issue(plate, IssueSource::Placement, IssueSeverity::Blocker, "right_nozzle_unprintable",
292	                                     get_right_extruder_unprintable_text()));
293	}
294	
295	// The filament and nozzle checks OrcaSlicer runs on a plate whenever it
296	// reloads the scene, asked again through the plate's own functions. The first
297	// two stop a slice; the rest are advice.
298	void PrintIssueMonitor::collect_plate_checks(PartPlate& plate, std::vector<PrintIssue>& issues) const
299	{
300	    if (!plate.has_printable_instances())
301	        return;
302	    PresetBundle&            bundle = *wxGetApp().preset_bundle;
303	    const DynamicPrintConfig config = bundle.full_config();
304	
305	    if (!plate.check_tpu_printable_status(config, bundle.get_used_tpu_filaments(plate.get_extruders(true))))
306	        issues.push_back(plate_issue(plate, IssueSource::PlateCheck, IssueSeverity::Blocker, "tpu_filaments",
307	                                     _u8L("Not support printing 2 or more TPU filaments.")));
308	    wxString filament_message;
309	    if (!plate.check_filament_printable(config, filament_message))
310	        issues.push_back(plate_issue(plate, IssueSource::PlateCheck, IssueSeverity::Blocker, "filament_not_printable",
311	                                     filament_message.ToUTF8().data()));
312	    if (!plate.check_mixture_of_pla_and_petg(config))
313	        issues.push_back(plate_issue(plate, IssueSource::PlateCheck, IssueSeverity::Warning, "pla_and_petg_mixed",
314	                                     _u8L("PLA and PETG filaments detected in the mixture. Adjust parameters according to the Wiki to ensure print quality.")));
315	    std::string nozzle_message;
316	    if (!plate.check_compatible_of_nozzle_and_filament(config, bundle.filament_presets, nozzle_message))
317	        issues.push_back(plate_issue(plate, IssueSource::PlateCheck, IssueSeverity::Warning, "nozzle_filament_incompatible",
318	                                     _u8L(nozzle_message)));
319	    std::string mixture_message;
320	    if (!plate.check_mixture_filament_compatible(config, mixture_message))
321	        issues.push_back(plate_issue(plate, IssueSource::PlateCheck, IssueSeverity::Warning, "filament_mixture_incompatible",
322	                                     _u8L(mixture_message)));
323	
324	    const GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
325	    const Print*      print  = plate.fff_print();
326	    if (canvas != nullptr && print != nullptr && print->is_step_done(psWipeTower) &&
327	        !canvas->get_volumes().check_wipe_tower_outside_state(m_plater.build_volume(), plate.get_index()))
328	        issues.push_back(plate_issue(plate, IssueSource::PlateCheck, IssueSeverity::Warning, "prime_tower_outside",
329	                                     _u8L("The prime tower extends beyond the plate boundary.")));
330	}
331	
332	// OrcaSlicer's own validation of the print, asked again. It holds one error
333	// and one warning at most; a later check overwrites an earlier warning.
334	void PrintIssueMonitor::collect_validation(PartPlate& plate, Print& print, std::vector<PrintIssue>& issues)
335	{
336	    // While a slice runs the print was valid when it started and any edit
337	    // that invalidates it would have stopped it, so the last answer stands.
338	    if (!m_plater.is_background_process_slicing()) {
339	        const auto started = std::chrono::steady_clock::now();
340	        StringObjectException warning{};
341	        Polygons              polygons;
342	        std::vector<std::pair<Polygon, float>> height_polygons;
343	        // As BackgroundSlicingProcess::validate does before it asks.
344	        print.is_BBL_printer() = wxGetApp().preset_bundle->is_bbl_vendor();
345	        StringObjectException error = print.validate(&warning, &polygons, &height_polygons);
346	        if (!error.string.empty())
347	            m_plater.post_process_string_object_exception(error);
348	        m_last_validate_ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - started).count();
349	        ++m_validate_runs;
350	
351	        m_validation.clear();
352	        const auto add = [&](const StringObjectException& result, bool blocker) {
353	            if (result.string.empty())
354	                return;
355	            PrintIssue issue;
356	            issue.source   = IssueSource::Validation;
357	            issue.severity = blocker ? IssueSeverity::Blocker : IssueSeverity::Warning;
358	            issue.code     = check_name(result.type);
359	            issue.setting  = result.opt_key;
360	            issue.message  = result.string;
361	            issue.plate    = plate.id().id;
362	            set_target(issue, result.object);
363	            issue.id = std::string("validation:") + (blocker ? "error" : "warning") + ":" + issue.setting + ":" + target_key(issue);
364	            m_validation.push_back(std::move(issue));
365	        };
366	        add(error, true);
367	        add(warning, false);
368	    }
369	    issues.insert(issues.end(), m_validation.begin(), m_validation.end());
370	}
371	
372	// Warnings the slicing steps left on the print and its objects. One whose
373	// step was invalidated stays on the print, marked not current, until the step
374	// runs again; it is reported the same way.
375	void PrintIssueMonitor::collect_steps(PartPlate& plate, const Print& print, std::vector<PrintIssue>& issues) const
376	{
377	    const auto collect = [&](const PrintStateBase::StateWithWarnings& state, const ModelObject* object, const char* scope, int step) {
378	        for (const PrintStateBase::Warning& warning : state.warnings) {
379	            PrintIssue issue;
380	            issue.source   = IssueSource::SliceStep;
381	            issue.severity = IssueSeverity::Warning;
382	            issue.code     = std::string(scope) + "_step_" + std::to_string(step) +
383	                             (warning.level == PrintStateBase::WarningLevel::CRITICAL ? ":critical" : "");
384	            issue.message  = warning.message;
385	            issue.plate    = plate.id().id;
386	            issue.stale    = !warning.current;
387	            set_target(issue, object, nullptr);
388	            // OrcaSlicer's rule: a message id names the warning; without one
389	            // the message itself does.
390	            issue.id = "slice_step:" + std::string(scope) + ":" + std::to_string(step) + ":" + target_key(issue) + ":" +
391	                       (warning.message_id != 0 ? std::to_string(warning.message_id) :
392	                                                  "m" + std::to_string(std::hash<std::string>{}(warning.message)));
393	            issues.push_back(std::move(issue));
394	        }
395	    };
396	    for (int step = 0; step < psCount; ++step)
397	        collect(print.step_state_with_warnings(static_cast<PrintStep>(step)), nullptr, "print", step);
398	    for (const PrintObject* object : print.objects())
399	        for (int step = 0; step < posCount; ++step)
400	            collect(object->step_state_with_warnings(static_cast<PrintObjectStep>(step)), object->model_object(), "object", step);
401	}
402	
403	// What a finished slice says about itself. The three that OrcaSlicer's own
404	// "ready to print" test refuses are blockers: a path outside the build
405	// volume, a filament a nozzle cannot print where it was placed, and a
406	// filament that cannot go on this plate's surface.
407	void PrintIssueMonitor::collect_result(PartPlate& plate, const Print& print, std::vector<PrintIssue>& issues)
408	{
409	    const GCodeProcessorResult* result = plate.get_slice_result();
410	    if (!plate.is_slice_result_valid() || m_plater.is_background_process_slicing() || result == nullptr) {
411	        m_result = {};
412	        return;
413	    }
414	
415	    if (const ConflictResultOpt conflict = print.get_conflict_result()) {
416	        PrintIssue issue = plate_issue(plate, IssueSource::SliceResult, IssueSeverity::Warning, "gcode_path_conflict",
417	                                       print.get_conflict_string());
418	        // The target the canvas gives its own notice.
419	        if (const auto* instance = reinterpret_cast<const PrintInstance*>(conflict->_obj2); instance != nullptr) {
420	            if (instance->model_instance != nullptr)
421	                set_target(issue, nullptr, instance->model_instance);
422	            else if (instance->print_object != nullptr)
423	                set_target(issue, instance->print_object->model_object(), nullptr);
424	        }
425	        issue.id += ":" + target_key(issue);
426	        issues.push_back(std::move(issue));
427	    }
428	
429	    if (m_result.result != result || m_result.result_id != result->id) {
430	        m_result = {result, result->id, {}};
431	        std::vector<PrintIssue>& found = m_result.issues;
432	
433	        for (const GCodeProcessorResult::SliceWarning& warning : result->warnings) {
434	            GCodeProcessorResult::SliceWarning copy = warning;
435	            const std::string text = Plater::get_slice_warning_string(copy).ToUTF8().data();
436	            if (text.empty())
437	                continue; // OrcaSlicer has no words for it and shows nothing itself
438	            found.push_back(plate_issue(plate, IssueSource::SliceResult, IssueSeverity::Warning,
439	                                        warning.error_code.empty() ? warning.msg : warning.error_code, text));
440	        }
441	
442	        // The result's own flag is only ever written when a sliced file is
443	        // loaded, so the build volume is asked, as the canvas asks it.
444	        const BuildVolume&  volume = m_plater.build_volume();
445	        const BoundingBoxf3 paths  = Workspace::extrusion_bounds(*result);
446	        if (paths.defined && !volume.all_paths_inside(*result, paths)) {
447	            const bool too_tall = volume.printable_height() > 0 && paths.max.z() > volume.printable_height() + BuildVolume::BedEpsilon;
448	            found.push_back(plate_issue(plate, IssueSource::SliceResult, IssueSeverity::Blocker,
449	                                        too_tall ? "toolpath_above_print_height" : "toolpath_outside_plate",
450	                                        too_tall ? _u8L("A G-code path goes beyond the max print height.") :
451	                                                   _u8L("A G-code path goes beyond the plate boundaries.")));
452	        }
453	
454	        // Which nozzle each filament was given and could not reach with, in
455	        // the sentences OrcaSlicer uses for it.
456	        const bool bbl = wxGetApp().preset_bundle->is_bbl_vendor();
457	        const auto nozzle = [bbl](int index, bool always_named) {
458	            if (bbl || always_named)
459	                return index == 0 ? _u8L("left nozzle") : _u8L("right nozzle");
460	            return (boost::format(_u8L("Tool %d")) % (index + 1)).str();
461	        };
462	        const auto per_nozzle = [&](const std::map<int, std::vector<std::pair<int, int>>>& errors, const char* code,
463	                                    const char* one, const char* several, bool always_named) {
464	            std::string text;
465	            for (const auto& [index, filaments_and_objects] : errors) {
466	                std::set<int> filaments;
467	                for (const auto& [filament, object] : filaments_and_objects)
468	                    filaments.insert(filament);
469	                const std::string name = nozzle(index, always_named);
470	                text += (text.empty() ? "" : "\n") +
471	                        (boost::format(filaments_and_objects.size() == 1 ? _u8L(one) : _u8L(several)) % filament_numbers(filaments) % name % name).str();
472	            }
473	            if (!text.empty())
474	                found.push_back(plate_issue(plate, IssueSource::SliceResult, IssueSeverity::Blocker, code, text));
475	        };
476	        if (result->gcode_check_result.error_code & 1)
477	            per_nozzle(result->gcode_check_result.print_area_error_infos, "nozzle_printable_area",
478	                       "Filament %s is placed in the %s, but the generated G-code path exceeds the printable range of the %s.",
479	                       "Filaments %s are placed in the %s, but the generated G-code path exceeds the printable range of the %s.", false);
480	        if (result->gcode_check_result.error_code & (1 << 1))
481	            per_nozzle(result->gcode_check_result.print_height_error_infos, "nozzle_printable_height",
482	                       "Filament %s is placed in the %s, but the generated G-code path exceeds the printable height of the %s.",
483	                       "Filaments %s are placed in the %s, but the generated G-code path exceeds the printable height of the %s.", true);
484	
485	        if (const std::vector<int>& unprintable = result->filament_printable_reuslt.conflict_filament; !unprintable.empty()) {
486	            std::string numbers;
487	            for (const int filament : unprintable)
488	                numbers += std::to_string(filament + 1) + " ";
489	            found.push_back(plate_issue(plate, IssueSource::SliceResult, IssueSeverity::Blocker, "filament_unprintable_on_plate",
490	                                        (boost::format(_u8L("Filaments %s cannot be printed directly on the surface of this plate.")) % numbers).str()));
491	        }
492	    }
493	    issues.insert(issues.end(), m_result.issues.begin(), m_result.issues.end());
494	}
495	
496	// Why the last slice of this plate failed. Only the completion event carries
497	// it, so it is the one thing kept here rather than read back. It goes stale
498	// when the project changes and is dropped when a slice starts.
499	void PrintIssueMonitor::collect_failure(PartPlate& plate, std::vector<PrintIssue>& issues) const
500	{
501	    const auto failure = m_failures.find(plate.id().id);
502	    if (failure == m_failures.end())
503	        return;
504	    const auto add = [&](const ModelObject* object) {
505	        PrintIssue issue = plate_issue(plate, IssueSource::SliceFailure, IssueSeverity::Blocker,
506	                                       failure->second.critical ? "critical" : "slicing_error", failure->second.message);
507	        issue.stale = failure->second.project_change != m_project_changes;
508	        set_target(issue, object, nullptr);
509	        issue.id = "slice_failure:" + target_key(issue);
510	        issues.push_back(std::move(issue));
511	    };
512	    bool targeted = false;
513	    for (const std::uint64_t id : failure->second.objects)
514	        for (const ModelObject* object : m_plater.model().objects)
515	            if (object->id().id == id) {
516	                add(object);
517	                targeted = true;
518	            }
519	    if (!targeted)
520	        add(nullptr);
521	}
522	
523	} // namespace Slic3r::GUI::JusPrin::PrintIssues
