3068	bool NotificationManager::update_notifications(GLCanvas3D& canvas)
3069	{
3070		// no update if not top window
3071		wxWindow* p = dynamic_cast<wxWindow*>(wxGetApp().plater());
3072		while (p->GetParent() != nullptr)
3073			p = p->GetParent();
3074		wxTopLevelWindow* top_level_wnd = dynamic_cast<wxTopLevelWindow*>(p);
3075		if (!top_level_wnd->IsActive())
3076			return false;
3077	
3078		// next_render() returns numeric_limits::max if no need for frame
3079		const int64_t max = std::numeric_limits<int64_t>::max();
3080		int64_t       next_render = max;
3081		const int64_t time_since_render = GLCanvas3D::timestamp_now() - m_last_render;
3082		bool		  request_render = false;
3083		// During render, each notification detects if its currently hovered and changes its state to EState::Hovered
3084		// If any notification is hovered, all restarts its countdown
3085		bool          hover = false;
3086		for (const std::unique_ptr<PopNotification>& notification : m_pop_notifications) {
3087			if (notification->is_hovered()) {
3088				hover = true;
3089				break;
3090			}
3091		}
3092		// update state of all notif and erase finished
3093		for (auto it = m_pop_notifications.begin(); it != m_pop_notifications.end();) {
3094			std::unique_ptr<PopNotification>& notification = *it;
3095			request_render |= notification->update_state(hover, time_since_render);
3096			next_render = std::min<int64_t>(next_render, notification->next_render());
3097			if (notification->get_state() == PopNotification::EState::Finished)
3098				it = m_pop_notifications.erase(it);
3099			else
3100				++it;
3101		}
3102	
3103		// delayed notifications
3104		for (auto it = m_waiting_notifications.begin(); it != m_waiting_notifications.end();) {
3105			// substract time
3106			if ((*it).remaining_time > 0)
3107				(*it).remaining_time -= time_since_render;
3108			if ((*it).remaining_time <= 0) {
3109				if ((*it).notification && (*it).condition_callback()) { // push notification, erase it from waiting list (frame is scheduled by push)
3110					(*it).notification->reset_timer();
3111					// if activate_existing returns false, we expect push to return true.
3112					if(!this->activate_existing((*it).notification.get()) || (*it).delay_interval == 0) {
3113						push_notification_data(std::move((*it).notification), 0);
3114						it = m_waiting_notifications.erase(it);
3115						continue;
3116					}
3117				}
3118				// not possible to push, delay for delay_interval
3119				(*it).remaining_time = (*it).delay_interval;
3120			}
3121			next_render = std::min<int64_t>(next_render, (*it).remaining_time);
3122			++it;
3123		}
3124	
3125		// request next frame in future
3126		if (next_render < max)
3127			canvas.schedule_extra_frame(int(next_render));
3128	
3129		return request_render;
3130	}
