3144	bool NotificationManager::activate_existing(const NotificationManager::PopNotification* notification)
3145	{
3146		NotificationType   new_type = notification->get_type();
3147		const std::string &new_text = notification->get_data().text1;
3148		for (auto it = m_pop_notifications.begin(); it != m_pop_notifications.end(); ++it) {
3149			if ((*it)->get_type() == new_type && !(*it)->is_finished()) {
3150				// multiple of one type allowed, but must have different text
3151				if (std::find(m_multiple_types.begin(), m_multiple_types.end(), new_type) != m_multiple_types.end()) {
3152					// If found same type and same text, return true - update will be performed on the old notif
3153					if ((*it)->compare_text(new_text) == false) {
3154						continue;
3155					}
3156				// multiple of one type allowed, but must have different text nad ObjectID
3157				} else if (new_type == NotificationType::SlicingWarning) {
3158					auto w1 = dynamic_cast<const ObjectIDNotification*>(notification);
3159					auto w2 = dynamic_cast<const ObjectIDNotification*>(it->get());
3160					if (w1 != nullptr && w2 != nullptr) {
3161						const NotificationData& data1 = w1->get_data();
3162						const NotificationData& data2 = w2->get_data();
3163						if (data1.sub_msg_id != data2.sub_msg_id)
3164							continue;
3165						//if (!(*it)->compare_text(new_text) || w1->object_id != w2->object_id) {
3166						//	continue;
3167						//}
3168					} else {
3169						continue;
3170					}
3171				}
3172				if (it != m_pop_notifications.end() - 1)
3173					std::rotate(it, it + 1, m_pop_notifications.end());
3174				return true;
3175			}
3176		}
3177		return false;
3178	}
