10058	void GLCanvas3D::_set_warning_notification_if_needed(EWarning warning)
10059	{
10060	    _set_current();
10061	    bool show = false;
10062	    if (!m_volumes.empty()) {
10063	        show = _is_any_volume_outside();
10064	        show &= m_gcode_viewer.has_data() && m_gcode_viewer.is_contained_in_bed() && m_gcode_viewer.m_conflict_result.has_value();
10065	    } else {
10066	        if (wxGetApp().is_editor()) {
10067	            if (current_printer_technology() != ptSLA) {
10068	                unsigned int max_z_layer = m_gcode_viewer.get_layers_z_range().back();
10069	                if (warning == EWarning::ToolHeightOutside) // check if max z_layer height exceed max print height
10070	                    show = m_gcode_viewer.has_data() && (m_gcode_viewer.get_layers_zs()[max_z_layer] - m_gcode_viewer.get_max_print_height() >= 1e-6);
10071	                else if (warning == EWarning::ToolpathOutside) { // check if max x,y coords exceed bed area
10072	                    show = m_gcode_viewer.has_data() && !m_gcode_viewer.is_contained_in_bed() &&
10073	                           (m_gcode_viewer.get_max_print_height() -m_gcode_viewer.get_layers_zs()[max_z_layer] >= 1e-6);
10074	                }
10075	                else if (warning == EWarning::GCodeConflict)
10076	                    show = m_gcode_viewer.has_data() && m_gcode_viewer.is_contained_in_bed() && m_gcode_viewer.m_conflict_result.has_value();
10077	                else if (warning == EWarning::MultiExtruderPrintableError)
10078	                    show = m_gcode_viewer.has_data() && (m_gcode_viewer.m_gcode_check_result.error_code & 1);
10079	                else if (warning == EWarning::MultiExtruderHeightOutside)
10080	                    show = m_gcode_viewer.has_data() && (m_gcode_viewer.m_gcode_check_result.error_code & (1 << 1));
10081	                else if (warning == EWarning::FilamentUnPrintableOnFirstLayer)
10082	                    show = m_gcode_viewer.has_data() && m_gcode_viewer.filament_printable_reuslt.has_value();
10083	            }
10084	        }
10085	    }
10086	
