10443	bool GLCanvas3D::is_flushing_matrix_error() {
10444	
10445	    // Flushing volumes only apply to single-extruder multi-material (SEMM) and BBL printers
10446	    if (!Sidebar::should_show_SEMM_buttons())
10447	        return false;
10448	
10449	    const auto                &project_config = wxGetApp().preset_bundle->project_config;
10450	    const std::vector<double> &config_matrix  = (project_config.option<ConfigOptionFloats>("flush_volumes_matrix"))->values;
10451	    const std::vector<double> &config_multiplier = (project_config.option<ConfigOptionFloats>("flush_multiplier"))->values;
10452	
10453	    for (auto multiplier : config_multiplier) {
10454	        if (multiplier == 0) return true;
10455	    }
10456	
10457	    int  matrix_len = config_matrix.size() / config_multiplier.size();
10458	    int  row_len    = std::sqrt(matrix_len);
10459	    for (int i = 0; i < config_matrix.size(); i++)
10460	    {
10461	        int relative_id = i % matrix_len;
10462	        int row_id      = relative_id / row_len;
10463	        int col_id      = relative_id % row_len;
10464	        if (row_id != col_id && config_matrix[i] == 0) return true;
10465	    }
10466	    return false;
10467	}
